def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    david_bid = None
    eric_bid = None
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append((agent_id, opp))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                name = str(agent_id).lower()
                if name == 'david':
                    david_bid = bid
                elif name == 'eric':
                    eric_bid = bid

    if not alive_opponents:
        return min(budget, 18.0)

    scarcity = supply <= 16
    moderate = supply <= 19

    if eric_bid is None:
        eric_bid = 137.2
    if david_bid is None:
        david_bid = 66.4

    highest_prev = max(prev_bids) if prev_bids else 0.0

    if hp <= 2 or no_water >= 2:
        target = max(eric_bid * 0.92, david_bid + 8.0, 150.0)
    elif hp <= 4 or no_water >= 1:
        if scarcity:
            target = max(david_bid + 6.0, eric_bid * 0.82, 118.0)
        else:
            target = max(david_bid + 4.0, 88.0)
    else:
        if scarcity:
            target = max(david_bid + 3.0, 79.0)
        elif moderate:
            target = max(david_bid + 1.5, 68.0)
        else:
            target = 22.0 if highest_prev > 120 else 36.0

    if budget < target:
        if hp <= 3 or no_water >= 1:
            return max(0.0, budget)
        return min(budget, 20.0)

    return max(0.0, min(budget, float(target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    hp = my_status['hp']
    budget = my_status['budget']

    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        if highest_prev >= DAILY_SALARY * 0.85:
            if hp > 3:
                bid = DAILY_SALARY * 0.3
            else:
                bid = DAILY_SALARY * 0.95
        else:
            bid = max(DAILY_SALARY * 0.55, highest_prev + 1.5)
    else:
        if hp <= 2:
            bid = DAILY_SALARY * 0.9
        else:
            bid = DAILY_SALARY * 0.55

    return min(float(budget), float(bid))
